            (""Training/imitator_loss"", self.get_recent_imitator_loss()),
        ]:
            # pyre-fixme[16]: `SummaryWriterContext` has no attribute `add_scalar`.
            SummaryWriterContext.add_scalar(name, none_to_zero(value), epoch)

